		t.Fatalf("其他货物不应受影响: %+v", cv2)
	}
	cpt, _ := r.Compartment("C1")
	if cpt.UsedWeight != 50 {
		t.Fatalf("舱位重量应保留: %+v", cpt)
	}
}

